"use strict";
// Zero-touch bootstrap: after one `npm i -g dsh-signoff`, nothing else is typed.
//
// Two layers, both idempotent and silent unless they change something:
//   1. repo layer  — the first gate run (or `npm i` inside a repo) writes .git/hooks,
//                    .signoff/config.json, .signoff/installed.json and the CI workflow.
//   2. machine layer — `core.hooksPath` points at ~/.signoff/hooks, so a fresh clone
//                    of any repo is guarded on the next commit without per-repo install.
// The machine layer delegates to the repo's own hook first, then to the gates, so an
// existing hook keeps its verdict.
//
// Opt out per shell with SIGNOFF_NO_BOOTSTRAP=1, per machine with `signoff uninstall --global`.

const fs = require("fs");
const path = require("path");
const os = require("os");
const { spawnSync } = require("child_process");
const core = require("./core");

const HOOK_MARK = "# generated by dsh-signoff";
const STATE = ".signoff";
const STAGES = ["pre-commit", "commit-msg", "pre-push"];

function gitRoot(cwd) {
  const r = spawnSync("git", ["rev-parse", "--show-toplevel"], { cwd, encoding: "utf8" });
  if (r.status !== 0) return null;
  const out = (r.stdout || "").trim().split(/\r?\n/).pop();
  return out ? out : null;
}

function gitDir(root) {
  const r = spawnSync("git", ["rev-parse", "--git-dir"], { cwd: root, encoding: "utf8" });
  if (r.status !== 0) return null;
  const raw = (r.stdout || "").trim();
  return path.isAbsolute(raw) ? raw : path.join(root, raw);
}

function readSafe(p) {
  try {
    return fs.readFileSync(p, "utf8");
  } catch (e) {
    return "";
  }
}

function isFile(p) {
  try {
    return fs.statSync(p).isFile();
  } catch (e) {
    return false;
  }
}

function hookState(root) {
  const gd = gitDir(root);
  const hooks = gd ? path.join(gd, "hooks") : null;
  const out = {};
  for (const stage of STAGES) {
    const p = hooks ? path.join(hooks, stage) : "";
    out[stage] = !!(p && isFile(p) && readSafe(p).includes(HOOK_MARK));
  }
  return out;
}

// What a repo still needs. `guarded` means every piece the hooks depend on exists.
function inspect(root) {
  const hooks = hookState(root);
  const st = path.join(root, STATE);
  const config = isFile(path.join(st, "config.json"));
  const installed = isFile(path.join(st, "installed.json"));
  const ci = isFile(path.join(root, ".github", "workflows", "signoff.yml"));
  const guarded = hooks["pre-commit"] && hooks["commit-msg"] && config;
  return { root, hooks, config, installed, ci, guarded };
}

// Write the package's init in `root` without touching the caller's cwd for longer than
// the call. guard.main reads process.cwd(), so the chdir is the seam.
function initRepo(root, quiet) {
  const guard = require("./guard");
  const before = process.cwd();
  let code = 1;
  try {
    process.chdir(root);
    code = guard.main(["init", "--chain", ...(quiet ? ["--quiet"] : [])]) || 0;
  } catch (e) {
    code = 1;
  } finally {
    process.chdir(before);
  }
  return code;
}

// Returns {ok, root, installed, changed[], code}. Never throws: it runs inside npm
// postinstall and inside git hooks, where a crash would be worse than a skipped install.
function ensureRepo(opts) {
  const o = opts || {};
  const cwd = o.cwd || process.cwd();
  const root = gitRoot(cwd);
  if (!root) {
    return { ok: false, root: null, installed: false, changed: [], reason: "not a git repository", code: 2 };
  }
  const before = inspect(root);
  if (before.guarded && before.installed) {
    return { ok: true, root, installed: false, changed: [], code: 0, state: before };
  }
  const code = initRepo(root, true);
  const after = inspect(root);
  const changed = [];
  if (!before.hooks["pre-commit"] && after.hooks["pre-commit"]) changed.push("hooks");
  if (!before.config && after.config) changed.push("config");
  if (!before.installed && after.installed) changed.push("installed.json");
  if (!before.ci && after.ci) changed.push("ci");
  return { ok: code === 0 && after.guarded, root, installed: changed.length > 0, changed, code, state: after };
}

// ---------------------------------------------------------------- machine layer

function globalHooksDir() {
  return path.join(core.homeDir(), "hooks");
}

function dispatcherBody(stage) {
  return `#!/bin/sh
${HOOK_MARK} ${require("../package.json").version} -- remove with: signoff uninstall --global
# Machine-wide dispatcher: hand the verdict to the repo's own hook first. If that hook is
# ours it already ran the gates, so stop there; otherwise add the light guard on top.
STAGE=${stage}
GITDIR=$(git rev-parse --git-dir 2>/dev/null) || exit 0
LOCAL="$GITDIR/hooks/$STAGE"
if [ -f "$LOCAL" ]; then
  if [ -x "$LOCAL" ]; then
    "$LOCAL" "$@" || exit $?
  else
    case "$LOCAL" in
      *.py) PY=$(command -v python3 || command -v python || command -v py) || { echo "[signoff] chained hook needs python: $LOCAL" >&2; exit 1; }; "$PY" "$LOCAL" "$@" || exit $? ;;
      *.js) node "$LOCAL" "$@" || exit $? ;;
      *.ps1) powershell -NoProfile -ExecutionPolicy Bypass -File "$LOCAL" "$@" || exit $? ;;
      *.cmd) cmd //c "$LOCAL" "$@" || exit $? ;;
      *) sh "$LOCAL" "$@" || exit $? ;;
    esac
  fi
  if grep -q "${HOOK_MARK}" "$LOCAL" 2>/dev/null; then
    exit 0
  fi
fi
if command -v signoff >/dev/null 2>&1; then
  exec signoff hook $STAGE "$@"
fi
if [ -f "./node_modules/dsh-signoff/bin/signoff.js" ]; then
  exec node "./node_modules/dsh-signoff/bin/signoff.js" hook $STAGE "$@"
fi
if [ "$STAGE" = "commit-msg" ]; then
  echo "[signoff] CLI not found: the commit continues, but it gets no Signoff trailer" >&2
  exit 0
fi
echo "[signoff] CLI not found: npm i -g dsh-signoff (or add it as a devDependency)" >&2
exit 1
`;
}

function writeExec(p, text) {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, text, "utf8");
  try {
    fs.chmodSync(p, 0o755);
  } catch (e) {
    /* Windows has no exec bit; git runs the hook through sh anyway. */
  }
}

function globalHooksPathSetting() {
  const r = spawnSync("git", ["config", "--global", "--get", "core.hooksPath"], { encoding: "utf8" });
  if (r.status !== 0) return "";
  return (r.stdout || "").trim();
}

function samePath(a, b) {
  if (!a || !b) return false;
  const norm = (p) => path.resolve(p).replace(/\\/g, "/").replace(/\/+$/, "").toLowerCase();
  const na = norm(a);
  const nb = norm(b);
  if (na === nb) return true;
  // git may store `~/...`; compare the expanded forms too.
  if (a.startsWith("~/")) return norm(path.join(os.homedir(), a.slice(2))) === nb;
  return false;
}

function setGlobalHooksPath(dir) {
  const value = dir.replace(/\\/g, "/");
  const r = spawnSync("git", ["config", "--global", "core.hooksPath", value], { encoding: "utf8" });
  return r.status === 0;
}

function ensureGlobal(opts) {
  const o = opts || {};
  const dir = globalHooksDir();
  const existing = globalHooksPathSetting();
  if (existing && !samePath(existing, dir) && !o.force) {
    return {
      ok: false,
      installed: false,
      dir,
      skipped: true,
      reason: `core.hooksPath already points at ${existing} (use --force to replace it)`,
      code: 0,
    };
  }
  const changed = [];
  for (const stage of STAGES) {
    const p = path.join(dir, stage);
    const body = dispatcherBody(stage);
    if (readSafe(p) !== body) {
      writeExec(p, body);
      changed.push(stage);
    }
  }
  const wrote = setGlobalHooksPath(dir);
  if (wrote) changed.push("core.hooksPath");
  return { ok: true, installed: changed.length > 0, dir, changed, code: 0 };
}

function uninstallGlobal() {
  const dir = globalHooksDir();
  const existing = globalHooksPathSetting();
  const owned = existing && samePath(existing, dir);
  if (owned) spawnSync("git", ["config", "--global", "--unset", "core.hooksPath"], { encoding: "utf8" });
  for (const stage of STAGES) {
    const p = path.join(dir, stage);
    if (isFile(p) && readSafe(p).includes(HOOK_MARK)) fs.rmSync(p, { force: true });
  }
  return { ok: true, owned, dir, removed: owned };
}

function status() {
  const root = gitRoot(process.cwd());
  const cfg = globalHooksPathSetting();
  const dir = globalHooksDir();
  return {
    repo: root,
    repoState: root ? inspect(root) : null,
    global: { configured: cfg, expected: dir.replace(/\\/g, "/"), active: !!cfg && samePath(cfg, dir) },
  };
}

// ---------------------------------------------------------------- CLI

const HELP = `signoff ensure — one-time (and then automatic) install

  signoff ensure                 guard this repo now: hooks, config, CI, ledger
  signoff ensure --global        guard every repo on this machine (core.hooksPath)
  signoff ensure --json          machine-readable result
  signoff ensure --quiet         say nothing unless something changed

Every gate command (p1..p5, all, guard, hook) runs the repo layer by itself, so a clone
that never saw \`signoff init\` is guarded on its first commit. Opt out with
SIGNOFF_NO_BOOTSTRAP=1; undo the machine layer with \`signoff uninstall --global\`.
`;

function run(argv) {
  const args = argv || [];
  if (args.includes("-h") || args.includes("--help")) {
    console.log(HELP);
    return 0;
  }
  const json = args.includes("--json");
  const quiet = args.includes("--quiet");
  const global = args.includes("--global");
  const force = args.includes("--force");
  const fromInstall = args.includes("--from-install");

  let repo = null;
  if (!global || fromInstall) {
    const cwd = fromInstall && process.env.INIT_CWD ? process.env.INIT_CWD : process.cwd();
    repo = ensureRepo({ cwd, quiet });
  }
  let machine = null;
  if (global || fromInstall) machine = ensureGlobal({ force });

  if (json) {
    console.log(JSON.stringify({ repo, machine }, null, 2));
  } else if (!quiet) {
    if (repo && repo.root) {
      console.log(repo.installed ? `signoff: guarded ${path.basename(repo.root)} (${repo.changed.join(", ")})` : `signoff: ${path.basename(repo.root)} already guarded`);
    } else if (repo) {
      console.log(`signoff: ${repo.reason}`);
    }
    if (machine) {
      if (machine.skipped) console.log(`signoff: machine layer skipped — ${machine.reason}`);
      else console.log(machine.installed ? `signoff: machine layer -> ${machine.dir}` : "signoff: machine layer already in place");
    }
  }

  // postinstall must never fail an npm install.
  if (fromInstall) return 0;
  if (repo && !repo.ok && repo.code === 2 && !global) return 2;
  if (repo && !repo.ok && repo.code) return 1;
  return 0;
}

module.exports = {
  HOOK_MARK,
  gitRoot,
  inspect,
  ensureRepo,
  ensureGlobal,
  uninstallGlobal,
  globalHooksDir,
  globalHooksPathSetting,
  status,
  run,
};
